(function(){
  if (window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1') {
    return;
  }
  const path=window.location.pathname;
  if(path.endsWith('.html')){
    let cleanPath=path.replace(/\.html$/i,'');
    if(cleanPath.endsWith('/index')){
      cleanPath=cleanPath.replace(/\/index$/,'/');
    }
    window.location.replace(cleanPath+window.location.search+window.location.hash);
  }
})();

let triggerConsultationPopup = null;
window.openConsultationPopup = function(force = true) {
  if (typeof triggerConsultationPopup === 'function') {
    triggerConsultationPopup(force);
  }
};

const initApp = () => {
  // Initialize Promo Top Banner
  const initPromoBanner = () => {
    if (sessionStorage.getItem('promoBannerClosed') === 'true') return;

    const styleEl = document.createElement('style');
    styleEl.innerHTML = `
      .promo-banner {
        position: fixed;
        top: 0;
        left: 0;
        right: 0;
        height: 44px;
        background-color: #189ba6 !important;
        color: #ffffff !important;
        z-index: 2000;
        display: flex;
        align-items: center;
        justify-content: center;
        font-size: 15px;
        font-weight: 500;
        text-align: center;
        padding: 0 40px;
        box-sizing: border-box;
      }
      .promo-banner-text {
        margin: 0;
        padding: 0;
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
        color: #ffffff !important;
      }
      .promo-banner-link {
        color: #ffffff !important;
        text-decoration: underline !important;
        font-weight: bold;
        margin-left: 6px;
        cursor: pointer;
        transition: color 0.2s;
      }
      .promo-banner-link:hover {
        color: #ffffff !important;
        opacity: 0.9;
      }
      .promo-banner-close {
        position: absolute;
        right: 12px;
        top: 50%;
        transform: translateY(-50%);
        color: #ffffff !important;
        font-size: 18px;
        font-weight: bold;
        cursor: pointer;
        opacity: 0.8;
        transition: opacity 0.2s;
        width: 28px;
        height: 28px;
        display: flex;
        align-items: center;
        justify-content: center;
      }
      .promo-banner-close:hover {
        opacity: 1;
      }
      @media (max-width: 576px) {
        .promo-banner {
          font-size: 12px;
          height: 40px;
          padding: 0 30px;
        }
        .promo-banner-close {
          right: 6px;
        }
      }
    `;
    document.head.appendChild(styleEl);

    const banner = document.createElement('div');
    banner.className = 'promo-banner';
    banner.innerHTML = `
      <span class="promo-banner-text">
        Grab 25% OFF on Modular Interiors! Hurry, book before July 31st, 2026!
        <a class="promo-banner-link" id="promoBannerLink">Get Offer &rang;</a>
      </span>
      <span class="promo-banner-close" id="promoBannerClose">&times;</span>
    `;

    document.body.insertBefore(banner, document.body.firstChild);

    const navbars = document.querySelectorAll('.fixed-top');
    const bannerHeight = banner.offsetHeight || 44;
    
    navbars.forEach(nav => {
      nav.style.top = bannerHeight + 'px';
      nav.style.transition = 'top 0.3s ease';
    });

    const originalPaddingTop = parseInt(getComputedStyle(document.body).paddingTop) || 0;
    document.body.style.paddingTop = (originalPaddingTop + bannerHeight) + 'px';

    document.getElementById('promoBannerLink').addEventListener('click', (e) => {
      e.preventDefault();
      if (typeof window.openConsultationPopup === 'function') {
        window.openConsultationPopup(true);
      }
    });

    document.getElementById('promoBannerClose').addEventListener('click', () => {
      sessionStorage.setItem('promoBannerClosed', 'true');
      banner.remove();
      
      navbars.forEach(nav => {
        nav.style.top = '0';
      });
      document.body.style.paddingTop = originalPaddingTop + 'px';
    });
  };

  initPromoBanner();

  const navbar=document.querySelector('.navbar');
  if (navbar) {
    navbar.classList.add('scrolled');
  }

  // Mobile Nav Background Scroll Lock
  const navbarCollapse = document.getElementById('navbarNav');
  if (navbarCollapse) {
    navbarCollapse.addEventListener('show.bs.collapse', () => {
      document.body.classList.add('mobile-nav-open');
    });
    navbarCollapse.addEventListener('hide.bs.collapse', () => {
      document.body.classList.remove('mobile-nav-open');
    });
  }


  const currentPath=window.location.pathname;
  const navLinks=document.querySelectorAll('.nav-link');
  
  navLinks.forEach(link=>{
  const href=link.getAttribute('href')||'';
  const pathClean=currentPath.replace(/\.html$/i,'').replace(/\/$/,'')||'/';
  const hrefClean=href.replace(/\.html$/i,'').replace(/\/$/,'')||'/';
  if(hrefClean===pathClean){
  link.classList.add('active');
 }else{
  link.classList.remove('active');
 }
});

 const filterButtons=document.querySelectorAll('.gallery-filter-btn');
 const galleryItems=document.querySelectorAll('.gallery-item');
 
 if(filterButtons.length>0){
 filterButtons.forEach(btn=>{
 btn.addEventListener('click',()=>{
 filterButtons.forEach(b=>b.classList.remove('active'));
 btn.classList.add('active');
 
 const filterValue=btn.getAttribute('data-filter');
 
 galleryItems.forEach(item=>{
 if(filterValue==='all'||item.classList.contains(filterValue)){
 item.style.display='block';
 setTimeout(()=>{
 item.style.opacity='1';
 item.style.transform='scale(1)';
},50);
}else{
 item.style.opacity='0';
 item.style.transform='scale(0.8)';
 setTimeout(()=>{
 item.style.display='none';
},300);
}
});
});
});
}

  const lightbox = document.getElementById('lightboxModal');
  const lightboxImg = document.getElementById('lightboxImg');
  const lightboxCaption = document.getElementById('lightboxCaption');
  const lightboxClose = document.querySelector('.lightbox-close');

  if (lightbox) {
    let activeTriggers = [];
    let currentIndex = 0;

    // Hide original static lightbox image since we use dynamic swiper track
    if (lightboxImg) {
      lightboxImg.style.display = 'none';
    }

    // Inject custom CSS styles for navigation arrows, swiper container, and slides
    const styleEl = document.createElement('style');
    styleEl.innerHTML = `
      /* Make entire gallery card clickable directly and style pointers */
      .premium-card-img {
        cursor: pointer !important;
      }
      
      /* Hide the text and expand the lightbox trigger to fill the overlay */
      .premium-card-overlay .btn-gold.lightbox-trigger {
        position: absolute !important;
        top: 0 !important;
        left: 0 !important;
        width: 100% !important;
        height: 100% !important;
        margin: 0 !important;
        padding: 0 !important;
        border: none !important;
        background: transparent !important;
        box-shadow: none !important;
        display: flex !important;
        align-items: center !important;
        justify-content: center !important;
        color: transparent !important;
        font-size: 0 !important;
      }
      
      /* Display a modern expand/zoom icon in the center */
      .premium-card-overlay .btn-gold.lightbox-trigger::after {
        content: '\\f065' !important; /* FontAwesome expand icon */
        font-family: 'Font Awesome 6 Free' !important;
        font-weight: 900 !important;
        color: #FFFFFF !important;
        font-size: 2rem !important;
        transition: transform 0.3s cubic-bezier(0.16, 1, 0.3, 1) !important;
        display: block !important;
      }
      
      .premium-card:hover .premium-card-overlay .btn-gold.lightbox-trigger::after {
        transform: scale(1.2) !important;
        color: var(--color-gold) !important;
      }
      
      /* Style next & prev navigation buttons inside the lightbox */
      .lightbox-prev, .lightbox-next {
        position: fixed !important;
        top: 50% !important;
        transform: translateY(-50%) !important;
        background: rgba(30, 28, 26, 0.5) !important;
        border: 1px solid rgba(255, 255, 255, 0.2) !important;
        color: #FFFFFF !important;
        font-size: 1.5rem !important;
        width: 50px !important;
        height: 50px !important;
        border-radius: 50% !important;
        display: flex !important;
        align-items: center !important;
        justify-content: center !important;
        cursor: pointer !important;
        z-index: 10005 !important;
        transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1) !important;
        backdrop-filter: blur(5px) !important;
        -webkit-backdrop-filter: blur(5px) !important;
      }
      
      .lightbox-prev {
        left: 20px !important;
      }
      
      .lightbox-next {
        right: 20px !important;
      }
      
      .lightbox-prev:hover, .lightbox-next:hover {
        background: var(--color-gold) !important;
        border-color: var(--color-gold) !important;
        color: #FFFFFF !important;
        transform: translateY(-50%) scale(1.1) !important;
      }
      
      .lightbox-prev:active, .lightbox-next:active {
        transform: translateY(-50%) scale(0.95) !important;
      }
      
      /* Style navigation arrows beautifully on mobile viewports */
      @media (max-width: 768px) {
        .lightbox-prev, .lightbox-next {
          width: 38px !important;
          height: 38px !important;
          font-size: 1.1rem !important;
        }
        .lightbox-prev {
          left: 10px !important;
        }
        .lightbox-next {
          right: 10px !important;
        }
      }
      
      /* Slider container and track layout matching Instagram carousel */
      .lightbox-slider-container {
        width: 85vw;
        height: 80vh;
        overflow: hidden;
        position: relative;
        display: flex;
        align-items: center;
        justify-content: center;
        touch-action: pan-y;
      }
      .lightbox-slider-track {
        display: flex;
        width: 300%;
        height: 100%;
        transform: translate3d(-85vw, 0, 0);
        will-change: transform;
      }
      .lightbox-slide {
        width: 85vw;
        height: 100%;
        display: flex;
        align-items: center;
        justify-content: center;
        flex-shrink: 0;
        user-select: none;
      }
      .lightbox-slide img {
        max-width: 85%;
        max-height: 75vh;
        object-fit: contain;
        border: 1px solid var(--color-gold);
        pointer-events: none;
        user-select: none;
        -webkit-user-drag: none;
      }
    `;
    document.head.appendChild(styleEl);

    // Create next and prev navigation buttons dynamically
    const lightboxContent = lightbox.querySelector('.lightbox-content');
    let prevBtn = lightbox.querySelector('.lightbox-prev');
    let nextBtn = lightbox.querySelector('.lightbox-next');

    if (lightboxContent && !prevBtn && !nextBtn) {
      prevBtn = document.createElement('button');
      prevBtn.className = 'lightbox-prev';
      prevBtn.innerHTML = '<i class="fas fa-chevron-left"></i>';
      prevBtn.setAttribute('aria-label', 'Previous Image');
      lightboxContent.appendChild(prevBtn);

      nextBtn = document.createElement('button');
      nextBtn.className = 'lightbox-next';
      nextBtn.innerHTML = '<i class="fas fa-chevron-right"></i>';
      nextBtn.setAttribute('aria-label', 'Next Image');
      lightboxContent.appendChild(nextBtn);
    }

    // Create the slider container programmatically inside the lightbox
    let sliderContainer = lightboxContent.querySelector('.lightbox-slider-container');
    if (!sliderContainer) {
      sliderContainer = document.createElement('div');
      sliderContainer.className = 'lightbox-slider-container';
      const sliderTrack = document.createElement('div');
      sliderTrack.className = 'lightbox-slider-track';
      sliderContainer.appendChild(sliderTrack);
      lightboxContent.insertBefore(sliderContainer, lightboxCaption);
    }
    const sliderTrack = sliderContainer.querySelector('.lightbox-slider-track');

    const prefetchAdjacentImages = (index) => {
      if (activeTriggers.length <= 1) return;
      const nextIndex = (index + 1) % activeTriggers.length;
      const prevIndex = (index - 1 + activeTriggers.length) % activeTriggers.length;
      [nextIndex, prevIndex].forEach(idx => {
        const trig = activeTriggers[idx];
        if (trig) {
          const src = trig.getAttribute('data-src') || trig.getAttribute('href');
          if (src) {
            const img = new Image();
            img.src = src;
          }
        }
      });
    };

    const openLightbox = (index) => {
      if (index < 0 || index >= activeTriggers.length) return;
      currentIndex = index;
      const total = activeTriggers.length;
      
      const currentTrigger = activeTriggers[currentIndex];
      const currentSrc = currentTrigger.getAttribute('data-src') || currentTrigger.getAttribute('href');
      const currentCaption = currentTrigger.getAttribute('data-caption') || '';
      
      const prevIndex = (currentIndex - 1 + total) % total;
      const nextIndex = (currentIndex + 1) % total;
      
      const prevTrigger = activeTriggers[prevIndex];
      const prevSrc = total > 1 ? (prevTrigger.getAttribute('data-src') || prevTrigger.getAttribute('href')) : '';
      
      const nextTrigger = activeTriggers[nextIndex];
      const nextSrc = total > 1 ? (nextTrigger.getAttribute('data-src') || nextTrigger.getAttribute('href')) : '';

            lightboxCaption.textContent = currentCaption;

      sliderTrack.innerHTML = '';
      sliderTrack.style.transition = 'none';

      lightbox.style.display = 'flex';
      document.body.style.overflow = 'hidden';

      if (total <= 1) {
        sliderTrack.style.width = '100%';
        sliderTrack.style.transform = 'translate3d(0px, 0, 0)';

        const activeSlide = document.createElement('div');
        activeSlide.className = 'lightbox-slide active-slide';
        activeSlide.style.width = '100%';
        activeSlide.style.height = '100%';
        activeSlide.style.display = 'flex';
        activeSlide.style.alignItems = 'center';
        activeSlide.style.justifyContent = 'center';
        activeSlide.innerHTML = `<img src="${currentSrc}" alt="${currentCaption}" />`;
        sliderTrack.appendChild(activeSlide);

        if (prevBtn) prevBtn.style.display = 'none';
        if (nextBtn) nextBtn.style.display = 'none';
      } else {
        sliderTrack.style.width = '300%';

        const prevSlide = document.createElement('div');
        prevSlide.className = 'lightbox-slide prev-slide';
        if (prevSrc) {
          prevSlide.innerHTML = `<img src="${prevSrc}" alt="Previous Image" />`;
        }
        sliderTrack.appendChild(prevSlide);

        const activeSlide = document.createElement('div');
        activeSlide.className = 'lightbox-slide active-slide';
        activeSlide.innerHTML = `<img src="${currentSrc}" alt="${currentCaption}" />`;
        sliderTrack.appendChild(activeSlide);

        const nextSlide = document.createElement('div');
        nextSlide.className = 'lightbox-slide next-slide';
        if (nextSrc) {
          nextSlide.innerHTML = `<img src="${nextSrc}" alt="Next Image" />`;
        }
        sliderTrack.appendChild(nextSlide);

        const width = sliderContainer.offsetWidth || (window.innerWidth * 0.85);
        sliderTrack.style.transform = `translate3d(-${width}px, 0, 0)`;

        if (prevBtn) prevBtn.style.display = 'flex';
        if (nextBtn) nextBtn.style.display = 'flex';
      }

      prefetchAdjacentImages(currentIndex);
    };

    const showNextImage = () => {
      if (activeTriggers.length <= 1) return;
      let nextIndex = currentIndex + 1;
      if (nextIndex >= activeTriggers.length) {
        nextIndex = 0;
      }
      openLightbox(nextIndex);
    };

    const showPrevImage = () => {
      if (activeTriggers.length <= 1) return;
      let prevIndex = currentIndex - 1;
      if (prevIndex < 0) {
        prevIndex = activeTriggers.length - 1;
      }
      openLightbox(prevIndex);
    };

    if (prevBtn) {
      prevBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        sliderTrack.style.transition = 'transform 0.25s cubic-bezier(0.16, 1, 0.3, 1)';
        sliderTrack.style.transform = 'translate3d(0px, 0, 0)';
        setTimeout(() => {
          showPrevImage();
        }, 250);
      });
    }

    if (nextBtn) {
      nextBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        const width = sliderContainer.offsetWidth || window.innerWidth;
        sliderTrack.style.transition = 'transform 0.25s cubic-bezier(0.16, 1, 0.3, 1)';
        sliderTrack.style.transform = `translate3d(-${2 * width}px, 0, 0)`;
        setTimeout(() => {
          showNextImage();
        }, 250);
      });
    }

    let initialScrollY = 0;
    let initialScrollX = 0;

    const recordScrollStart = () => {
      initialScrollY = window.scrollY || window.pageYOffset;
      initialScrollX = window.scrollX || window.pageXOffset;
    };

    document.addEventListener('touchstart', recordScrollStart, { passive: true });
    document.addEventListener('mousedown', recordScrollStart, { passive: true });

    const handleLightboxOpen = (e) => {
      const currentScrollY = window.scrollY || window.pageYOffset;
      const currentScrollX = window.scrollX || window.pageXOffset;
      const scrolledY = Math.abs(currentScrollY - initialScrollY);
      const scrolledX = Math.abs(currentScrollX - initialScrollX);

      if (scrolledY > 5 || scrolledX > 5) {
        return;
      }

      const trigger = e.target.closest('.lightbox-trigger');
      const cardImg = e.target.closest('.premium-card-img');
      
      let targetTrigger = null;
      if (trigger) {
        targetTrigger = trigger;
      } else if (cardImg) {
        targetTrigger = cardImg.querySelector('.lightbox-trigger');
      }

            if (targetTrigger) {
        e.preventDefault();
        
        const cardImgContainer = targetTrigger.closest('.premium-card-img, .premium-card, .dc-exact-card-img');
        if (cardImgContainer) {
          const cardImgs = Array.from(cardImgContainer.querySelectorAll('.carousel-inner img, img'));
          const clickedImg = e.target.tagName === 'IMG' ? e.target : cardImgContainer.querySelector('.carousel-item.active img') || cardImgs[0];
          
          if (clickedImg && typeof window.openLightbox === 'function') {
            window.openLightbox(clickedImg);
            return;
          }
        }

        activeTriggers = Array.from(document.querySelectorAll('.lightbox-trigger')).filter(t => {
          return t.offsetWidth > 0 || t.offsetHeight > 0;
        });

        const index = activeTriggers.indexOf(targetTrigger);
        if (index !== -1) {
          openLightbox(index);
        }
      }
    };

    const closeLightbox = () => {
      lightbox.style.display = 'none';
      sliderTrack.innerHTML = '';
      lightboxCaption.textContent = '';
      document.body.style.overflow = '';
    };

    if (lightboxClose) {
      lightboxClose.addEventListener('click', closeLightbox);
    }

    lightbox.addEventListener('click', (e) => {
      // Close only if clicking outside the image and navigation buttons
      if (e.target === lightbox || e.target === lightboxCaption) {
        closeLightbox();
      }
    });

    // Keyboard navigation controls
    document.addEventListener('keydown', (e) => {
      if (lightbox.style.display === 'flex') {
        if (e.key === 'ArrowRight') {
          showNextImage();
        } else if (e.key === 'ArrowLeft') {
          showPrevImage();
        } else if (e.key === 'Escape') {
          closeLightbox();
        }
      }
    });

    // Swipe/Drag scrolling implementation (Instagram style)
    let startX = 0;
    let currentX = 0;
    let isDragging = false;
    let containerWidth = 0;

    const getTouchX = (e) => {
      return e.touches ? e.touches[0].clientX : e.clientX;
    };

    const handleDragStart = (e) => {
      if (activeTriggers.length <= 1) return;
      if (e.target.closest('.lightbox-close') || e.target.closest('#lightboxCaption')) return;
      
      isDragging = true;
      startX = getTouchX(e);
      currentX = startX;
      containerWidth = sliderContainer.offsetWidth || window.innerWidth;
      sliderTrack.style.transition = 'none';
    };

    const handleDragMove = (e) => {
      if (!isDragging) return;
      currentX = getTouchX(e);
      const deltaX = currentX - startX;
      const translation = -containerWidth + deltaX;
      sliderTrack.style.transform = `translate3d(${translation}px, 0, 0)`;
    };

    const handleDragEnd = () => {
      if (!isDragging) return;
      isDragging = false;
      const deltaX = currentX - startX;
      const threshold = containerWidth * 0.15; // 15% swipe threshold

      sliderTrack.style.transition = 'transform 0.25s cubic-bezier(0.16, 1, 0.3, 1)';

      if (deltaX > threshold) {
        // Swiped right -> show previous slide
        sliderTrack.style.transform = `translate3d(0px, 0, 0)`;
        setTimeout(() => {
          showPrevImage();
        }, 250);
      } else if (deltaX < -threshold) {
        // Swiped left -> show next slide
        sliderTrack.style.transform = `translate3d(-${2 * containerWidth}px, 0, 0)`;
        setTimeout(() => {
          showNextImage();
        }, 250);
      } else {
        // Snap back to center active slide
        sliderTrack.style.transform = `translate3d(-${containerWidth}px, 0, 0)`;
      }
    };

    // Left/Right side click tap navigation + background click close
    sliderContainer.addEventListener('click', (e) => {
      if (isDragging || Math.abs(currentX - startX) > 8) return;
      
      // Close if clicking outside the image boundaries (on the slide background itself)
      if (e.target.classList.contains('lightbox-slide')) {
        closeLightbox();
        return;
      }

      if (e.target.closest('.lightbox-close')) return;

      // Disable left/right click navigation if there's only 1 image
      if (activeTriggers.length <= 1) return;

      const rect = sliderContainer.getBoundingClientRect();
      const clickX = e.clientX - rect.left;
      const width = rect.width;

      sliderTrack.style.transition = 'transform 0.25s cubic-bezier(0.16, 1, 0.3, 1)';

      if (clickX < width * 0.4) {
        sliderTrack.style.transform = `translate3d(0px, 0, 0)`;
        setTimeout(() => {
          showPrevImage();
        }, 250);
      } else {
        sliderTrack.style.transform = `translate3d(-${2 * width}px, 0, 0)`;
        setTimeout(() => {
          showNextImage();
        }, 250);
      }
    });

    // Provide visual navigation cursor arrows on hover (only if multiple images exist)
    sliderContainer.addEventListener('mousemove', (e) => {
      if (activeTriggers.length <= 1) {
        sliderContainer.style.cursor = 'default';
        return;
      }
      const rect = sliderContainer.getBoundingClientRect();
      const hoverX = e.clientX - rect.left;
      const width = rect.width;
      
      if (hoverX < width * 0.4) {
        sliderContainer.style.cursor = 'w-resize';
      } else {
        sliderContainer.style.cursor = 'e-resize';
      }
    });

    // Register touch events
    sliderContainer.addEventListener('touchstart', handleDragStart, { passive: true });
    sliderContainer.addEventListener('touchmove', handleDragMove, { passive: true });
    sliderContainer.addEventListener('touchend', handleDragEnd);

    // Register mouse events for drag/swipe support on desktop
    sliderContainer.addEventListener('mousedown', (e) => {
      if (e.button !== 0) return;
      handleDragStart(e);
    });
    sliderContainer.addEventListener('mousemove', handleDragMove);
    sliderContainer.addEventListener('mouseup', handleDragEnd);
    sliderContainer.addEventListener('mouseleave', () => {
      if (isDragging) handleDragEnd();
    });
  }

 const baSlider=document.querySelector('.ba-slider');
 if(baSlider){
 const handle=baSlider.querySelector('.ba-handle');
 const afterImg=baSlider.querySelector('.ba-after');
 let isDragging=false;

 const setSliderPos=(x)=>{
 const rect=baSlider.getBoundingClientRect();
 let position=((x-rect.left)/rect.width)*100;
 
 if(position<0)position=0;
 if(position>100)position=100;
 
 handle.style.left=`${position}%`;
 afterImg.style.width=`${position}%`;
};

 const handleStart=(e)=>{
 isDragging=true;
 const x=e.type.includes('touch')? e.touches[0].clientX:e.clientX;
 setSliderPos(x);
};

 const handleMove=(e)=>{
 if(!isDragging)return;
 const x=e.type.includes('touch')? e.touches[0].clientX:e.clientX;
 setSliderPos(x);
};

 const handleEnd=()=>{
 isDragging=false;
};

 baSlider.addEventListener('mousedown',handleStart);
 window.addEventListener('mousemove',handleMove);
 window.addEventListener('mouseup',handleEnd);

 baSlider.addEventListener('touchstart',handleStart);
 window.addEventListener('touchmove',handleMove);
 window.addEventListener('touchend',handleEnd);
}

 const calcForm=document.getElementById('calculatorForm');
 const calcResult=document.getElementById('calcResult');
 
 if(calcForm&&calcResult){
 calcForm.addEventListener('submit',(e)=>{
 e.preventDefault();
 
 const propType=document.getElementById('propType').value;
 const size=parseFloat(document.getElementById('size').value)||0;
 const quality=document.getElementById('quality').value;
 
 if(!size||size<=0){
 alert('Please enter a valid property size in Sq. Ft.');
 return;
}

 let ratePerSqFt=0;
 if(quality==='standard'){
 ratePerSqFt=950;
}else if(quality==='premium'){
 ratePerSqFt=1600;
}else if(quality==='luxury'){
 ratePerSqFt=2800;
}

 let multiplier=1.0;
 if(propType==='modular-kitchen'){
 multiplier=1.3;
}else if(propType==='villa'){
 multiplier=1.15;
}else if(propType==='office'||propType==='commercial'){
 multiplier=0.9;
}

 const estimatedCost=size*ratePerSqFt*multiplier;
 const minCost=Math.round(estimatedCost*0.9);
 const maxCost=Math.round(estimatedCost*1.1);

 const formatRupee=(num)=>{
 return new Intl.NumberFormat('en-IN',{
 style:'currency',
 currency:'INR',
 maximumFractionDigits:0
}).format(num);
};

 calcResult.innerHTML=`
<h4 class="text-gold mb-3 font-luxury">Your Estimated Cost</h4>
<h2 class="text-white mb-2" style="font-weight:700;">${formatRupee(minCost)}-${formatRupee(maxCost)}*</h2>
<p class="small text-muted mb-4">*Prices are estimates based on average Navi Mumbai local contractor rates including material and labour. Detailed site visits are required for finalized plans.</p>
<div class="d-grid gap-2">
<a href="https://wa.me/918369297174?text=Hi%20Siddhivinayak%20Designers,%20I%20just%20calculated%20my%20interior%20cost%20estimation%20for%20a%20${size}%20sqft%20${propType}%20as%20${formatRupee(estimatedCost)}.%20Please%20schedule%20a%20free%20consultation." class="btn btn-gold" target="_blank">
<i class="fab fa-whatsapp me-2"></i>Discuss on WhatsApp
</a>
</div>
 `;
});
}

 const contactForm=document.getElementById('contactForm');
 const quoteForm=document.getElementById('quoteForm');

 const handleFormSubmit=(form,formType)=>{
 if(!form)return;
 form.addEventListener('submit',(e)=>{
 e.preventDefault();
 
 const inputs=form.querySelectorAll('input[required],select[required],textarea[required]');
 let isValid=true;
 inputs.forEach(input=>{
 if(!input.value.trim()){
 isValid=false;
 input.classList.add('is-invalid');
 }else{
 input.classList.remove('is-invalid');
 }
 });

 if(!isValid)return;

 // Show submitting indicator
 const submitBtn = form.querySelector('[type="submit"]');
 const originalBtnText = submitBtn ? submitBtn.innerHTML : 'Submit';
 if(submitBtn) {
   submitBtn.disabled = true;
   submitBtn.innerHTML = '<i class="fas fa-spinner fa-spin me-2"></i>Submitting...';
 }

 // Gather data
 const name = form.querySelector('[name="name"]')?.value || '';
 const phone = form.querySelector('[name="phone"]')?.value || '';
 const email = form.querySelector('[name="email"]')?.value || '';
 const location = form.querySelector('[name="location"]')?.value || '';
 const property = form.querySelector('[name="property"]')?.value || '';
 const budget = form.querySelector('[name="budget"]')?.value || '';
 const messageInput = form.querySelector('[name="message"]')?.value || '';

 // Map service details dynamically
 let serviceVal = formType;
 if (property || location) {
   serviceVal = `${property || ''} in ${location || ''}`;
   if (budget) serviceVal += ` (Budget: ${budget})`;
 }

 // Prepare URL encoded payload
 const url = 'https://script.google.com/macros/s/AKfycbyaOLtqYYNWRfjIuyBnW81_RnYziWCuSqO660SKF3n4N3w4vL7GNqvYb58o-3K29e6I/exec';
 const params = new URLSearchParams();
 params.append('name', name);
 params.append('phone', phone);
 params.append('email', email);
 params.append('service', serviceVal);
 params.append('message', messageInput);

 fetch(url, {
   method: 'POST',
   mode: 'no-cors', // standard cross-origin fetch for Apps Script doPost
   headers: {
     'Content-Type': 'application/x-www-form-urlencoded'
   },
   body: params.toString()
 })
 .then(() => {
   const container=form.parentElement;
   container.innerHTML=`
     <div class="text-center py-5" data-aos="fade-up">
       <div class="mb-4">
         <i class="fas fa-check-circle text-gold" style="font-size:4rem;"></i>
       </div>
       <h3 class="text-white font-luxury mb-3">Thank you, ${name}!</h3>
       <p class="text-muted">Your request has been submitted successfully to our design database. A dedicated project manager from Siddhivinayak Designers will contact you within the next 24 hours.</p>
       <a href="/" class="btn btn-outline-gold mt-4">Go Back Home</a>
     </div>
   `;
 })
 .catch(err => {
   console.error("Submission error:", err);
   if(submitBtn) {
     submitBtn.disabled = false;
     submitBtn.innerHTML = originalBtnText;
   }
   alert("There was an error submitting your request. Please try again or contact us directly on WhatsApp!");
 });
 });
 };

 handleFormSubmit(contactForm,'Contact Form');
 handleFormSubmit(quoteForm,'Quick Quote');

  const decodeEmail=()=>{
  document.querySelectorAll('.email-link').forEach(link=>{
  const user=link.getAttribute('data-user');
  const domain=link.getAttribute('data-domain');
  if(user&&domain){
  const email=`${user}@${domain}`;
  link.setAttribute('href',`mailto:${email}`);
  if(link.textContent.trim().includes('[at]')){
  link.textContent=email;
 }
 }
 });
  document.querySelectorAll('.email-text').forEach(el=>{
  const user=el.getAttribute('data-user');
  const domain=el.getAttribute('data-domain');
  if(user&&domain){
  el.textContent=`${user}@${domain}`;
 }
 });
 };
  decodeEmail();

  // --- LEAD CAPTURE CONSULTATION POPUP CONTROLLER (FULLY NAMESPACED AND ISOLATED) ---
  let triggerConsultationPopup = null;

  window.openConsultationPopup = function(force = true) {
    if (typeof triggerConsultationPopup === 'function') {
      triggerConsultationPopup(force);
    }
  };

  const initConsultationPopup = () => {
    let popupTimer = null;

    const showPopup = (force = false) => {
      const isSubmitted = localStorage.getItem('consultationFormSubmitted') === 'true';
      if (isSubmitted && !force) return;

      // If forcing (e.g. user clicked photo), recreate fresh modal
      const existingPopup = document.getElementById('consultationPopup');
      if (existingPopup) {
        if (force) {
          existingPopup.remove();
        } else {
          existingPopup.classList.add('active');
          document.body.style.overflow = 'hidden';
          return;
        }
      }

      // Create modal markup with namespaced classes
      const popupOverlay = document.createElement('div');
      popupOverlay.className = 'consultation-popup-overlay';
      popupOverlay.id = 'consultationPopup';
      
      popupOverlay.innerHTML = `
        <div class="consultation-popup-container">
          <button class="consultation-popup-close" id="closeConsultationPopup" aria-label="Close modal">&times;</button>
          <div class="consultation-popup-left">
            <img src="/assets/images/popup-banner.webp?v=2" alt="Siddhivinayak Designers Consultation Banner" class="consultation-popup-img">
          </div>
          <div class="consultation-popup-right">
            <div class="consultation-popup-form-wrapper" id="consultationFormWrapper">
              <h3 class="consultation-popup-title">Get a <span class="consultation-popup-text-gold">free</span> design consultation</h3>
              <form id="popupConsultationForm" class="consultation-popup-form">
                <div class="consultation-popup-form-group">
                  <label class="consultation-popup-label">Property Type</label>
                  <div class="consultation-popup-property-selector">
                    <button type="button" class="consultation-popup-prop-btn active" data-value="1 BHK">1 BHK</button>
                    <button type="button" class="consultation-popup-prop-btn" data-value="2 BHK">2 BHK</button>
                    <button type="button" class="consultation-popup-prop-btn" data-value="3 BHK">3 BHK</button>
                    <button type="button" class="consultation-popup-prop-btn" data-value="4+ BHK / Duplex">4+ BHK / Duplex</button>
                  </div>
                  <input type="hidden" name="propertyType" id="selectedPropertyType" value="1 BHK">
                </div>
                
                <div class="consultation-popup-form-group">
                  <label for="popupLocation" class="consultation-popup-label">Property Location</label>
                  <select class="consultation-popup-select" id="popupLocation" required>
                    <option value="" disabled selected>Select Location in Navi Mumbai</option>
                    <option value="Kopar Khairane">Kopar Khairane</option>
                    <option value="Vashi">Vashi</option>
                    <option value="Nerul">Nerul</option>
                    <option value="Kharghar">Kharghar</option>
                    <option value="Panvel">Panvel</option>
                    <option value="Belapur">Belapur</option>
                    <option value="Sanpada">Sanpada</option>
                    <option value="Ghansoli">Ghansoli</option>
                    <option value="Airoli">Airoli</option>
                    <option value="Seawoods">Seawoods</option>
                    <option value="Ulwe">Ulwe</option>
                    <option value="Kamothe">Kamothe</option>
                    <option value="Kalamboli">Kalamboli</option>
                    <option value="Other">Other / Outside Navi Mumbai</option>
                  </select>
                </div>

                <div class="consultation-popup-form-group">
                  <label for="popupName" class="consultation-popup-label">Name</label>
                  <input type="text" class="consultation-popup-input" id="popupName" placeholder="Enter your name" required>
                </div>

                <div class="consultation-popup-form-group">
                  <label for="popupPhone" class="consultation-popup-label">Mobile Number</label>
                  <div class="consultation-popup-input-group">
                    <span class="consultation-popup-input-group-addon">+91</span>
                    <input type="tel" class="consultation-popup-input consultation-popup-input-phone" id="popupPhone" placeholder="10-digit mobile number" pattern="[6-9][0-9]{9}" required>
                  </div>
                </div>

                <div class="consultation-popup-form-group consultation-popup-checkbox-group">
                  <input type="checkbox" class="consultation-popup-checkbox" id="popupWhatsapp" checked>
                  <label class="consultation-popup-checkbox-label" for="popupWhatsapp">
                    Yes, send me updates via WhatsApp <i class="fab fa-whatsapp" style="color: #25d366; margin-left: 4px;"></i>
                  </label>
                </div>

                <div class="consultation-popup-submit-container">
                  <button type="submit" class="consultation-popup-btn-submit" id="popupSubmitBtn">Book a Free Consultation</button>
                </div>
                
                <div class="consultation-popup-footer-text">
                  By submitting, you consent to our <a href="/privacy-policy.html" target="_blank" class="consultation-popup-link-gold">privacy policy</a> & <a href="/terms-conditions.html" target="_blank" class="consultation-popup-link-gold">terms of use</a>
                </div>
              </form>
            </div>
          </div>
        </div>
      `;

      document.body.appendChild(popupOverlay);

      // Force reflow for CSS transition
      setTimeout(() => {
        popupOverlay.classList.add('active');
        document.body.style.overflow = 'hidden';
      }, 50);

      if (popupTimer) clearTimeout(popupTimer);

      // --- EVENT HANDLERS ---
      const closePopupBtn = document.getElementById('closeConsultationPopup');
      const closePopup = () => {
        popupOverlay.classList.remove('active');
        document.body.style.overflow = '';
        sessionStorage.setItem('consultationPopupClosedSession', 'true');
        setTimeout(() => {
          popupOverlay.remove();
          popupTimer = setTimeout(() => showPopup(false), 30000);
        }, 500);
      };
      
      if (closePopupBtn) closePopupBtn.addEventListener('click', closePopup);
      popupOverlay.addEventListener('click', (e) => {
        if (e.target === popupOverlay) {
          closePopup();
        }
      });

      // Property Type Selector Chips
      const propBtns = popupOverlay.querySelectorAll('.consultation-popup-prop-btn');
      const selectedPropInput = document.getElementById('selectedPropertyType');
      propBtns.forEach(btn => {
        btn.addEventListener('click', () => {
          propBtns.forEach(b => b.classList.remove('active'));
          btn.classList.add('active');
          selectedPropInput.value = btn.getAttribute('data-value');
        });
      });

      // Form submission handler
      const popupForm = document.getElementById('popupConsultationForm');
      if (popupForm) {
        popupForm.addEventListener('submit', (e) => {
          e.preventDefault();

          const propertyType = selectedPropInput.value;
          const location = document.getElementById('popupLocation').value;
          const name = document.getElementById('popupName').value;
          const phone = document.getElementById('popupPhone').value;
          const whatsappConsent = document.getElementById('popupWhatsapp').checked;

          const submitBtn = document.getElementById('popupSubmitBtn');
          const originalText = submitBtn.innerHTML;
          submitBtn.disabled = true;
          submitBtn.innerHTML = '<i class="fas fa-spinner fa-spin me-2"></i>Booking...';

          const serviceVal = `Popup Consultation: ${propertyType} in ${location}`;
          const messageVal = `Consent to WhatsApp/RCS updates: ${whatsappConsent ? 'Yes' : 'No'}`;

          const url = 'https://script.google.com/macros/s/AKfycbyaOLtqYYNWRfjIuyBnW81_RnYziWCuSqO660SKF3n4N3w4vL7GNqvYb58o-3K29e6I/exec';
          const params = new URLSearchParams();
          params.append('name', name);
          params.append('phone', `+91${phone}`);
          params.append('email', 'popup-lead@siddhivinayakdesigners.in');
          params.append('service', serviceVal);
          params.append('message', messageVal);

          fetch(url, {
            method: 'POST',
            mode: 'no-cors',
            headers: {
              'Content-Type': 'application/x-www-form-urlencoded'
            },
            body: params.toString()
          })
          .then(() => {
            localStorage.setItem('consultationFormSubmitted', 'true');
            
            const container = document.getElementById('consultationFormWrapper');
            container.innerHTML = `
              <div class="text-center py-4" style="animation: fadeInUp 0.5s ease forwards;">
                <div class="mb-4">
                  <i class="fas fa-check-circle text-gold" style="font-size: 3.5rem;"></i>
                </div>
                <h3 class="text-dark font-luxury mb-3">Thank you, ${name}!</h3>
                <p class="text-muted small">Your design consultation has been successfully booked. Our expert designer will contact you within 24 hours.</p>
                <button class="consultation-popup-btn-submit mt-3 px-4" id="closePopupSuccessBtn" style="width: auto !important; display: inline-block;">Close</button>
              </div>
            `;
            
            document.getElementById('closePopupSuccessBtn').addEventListener('click', () => {
              popupOverlay.classList.remove('active');
              document.body.style.overflow = '';
              setTimeout(() => popupOverlay.remove(), 500);
            });
          })
          .catch(err => {
            console.error("Popup submission error:", err);
            submitBtn.disabled = false;
            submitBtn.innerHTML = originalText;
            alert("There was an error booking your consultation. Please try again or message us on WhatsApp directly!");
          });
        });
      }
    };

    triggerConsultationPopup = showPopup;

    const isSubmitted = localStorage.getItem('consultationFormSubmitted') === 'true';
    if (!isSubmitted) {
      const isClosedInSession = sessionStorage.getItem('consultationPopupClosedSession') === 'true';
      const initialDelay = isClosedInSession ? 30000 : 3000;
      popupTimer = setTimeout(() => showPopup(false), initialDelay);
    }
  };

  initConsultationPopup();

  // Global click handler specifically for main index hero banner photos
  document.addEventListener('click', (e) => {
    const target = e.target;
    if (!target) return;

    const isHeroImg = target.classList.contains('hero-banner-img') || 
                      target.closest('.hero-banner-img') ||
                      target.closest('#heroBannerCarousel .carousel-item') ||
                      target.closest('.hero-banner-popup-trigger');
                      
    const isCarouselControl = target.closest('.carousel-control-prev') || 
                              target.closest('.carousel-control-next') || 
                              target.closest('.carousel-indicators');

    if (isHeroImg && !isCarouselControl) {
      e.preventDefault();
      e.stopPropagation();
      window.openConsultationPopup(true);
    }
  }, true);
};

